lseif $1 > data.p50.score then\n minCoeff, maxCoeff = data.p50.min, data.p50.max\n baseprice = data.baseprice\nelseif $1 > data.p30.score then\n minCoeff, maxCoeff = data.p30.min, data.p30.max\n baseprice = data.baseprice\nelse\n minCoeff, maxCoeff = data.Default.min, data.Default.max\n baseprice = data.baseprice\nend\n\nlocal шаг = 0,05\nlocal шаги = Floor((maxCoeff - minCoeff) / шаг + 0,5)\nlocal randIndex = Random(0, шаги)\nlocal result = minCoeff + randIndex * шаг\n\nreturn Round(Floor(result * 100 + 0,5) / 100 * базовая цена)",
